<?php
// zero-relay.php — command relay between Zero AI (web) and the user's "Zero Computer" Chrome extension.
// The AI drives; the viewer just watches.
//
// Auth: 32-char pairing key on EVERY request (generated by the extension, entered once in Zero AI).
// No guard.php origin check here: chrome-extension:// origins can't pass it, and the key is the credential.
// CORS reflects the Zero site or any chrome-extension:// caller; the key remains the real auth.
header("Content-Type: application/json; charset=utf-8");

$origin = $_SERVER["HTTP_ORIGIN"] ?? "";
if ($origin === "https://zero.page.gd" || strpos($origin, "chrome-extension://") === 0) {
    header("Access-Control-Allow-Origin: " . $origin);
}
header("Access-Control-Allow-Methods: POST, GET, OPTIONS");
header("Access-Control-Allow-Headers: Content-Type");
if (($_SERVER["REQUEST_METHOD"] ?? "") === "OPTIONS") { http_response_code(204); exit; }

// --- light per-IP rate limit (120/min), same pattern as guard.php ---
$ip = $_SERVER["REMOTE_ADDR"] ?? "unknown";
$rlDir = sys_get_temp_dir() . "/zero_relay_rl";
if (!is_dir($rlDir)) { @mkdir($rlDir, 0700, true); }
$rlFile = $rlDir . "/" . preg_replace("/[^a-f0-9.:]/i", "", $ip) . ".json";
$now = time();
$rl = ["t" => $now, "n" => 0];
if (is_file($rlFile)) {
    $d = json_decode(@file_get_contents($rlFile), true);
    if (is_array($d) && isset($d["t"]) && ($now - $d["t"]) < 60) { $rl = $d; }
}
$rl["n"]++;
@file_put_contents($rlFile, json_encode(["t" => $rl["t"], "n" => $rl["n"]]));
if ($rl["n"] > 120) { http_response_code(429); echo json_encode(["error" => "rate_limited"]); exit; }

$RDIR = __DIR__ . "/zero-relay";
if (!is_dir($RDIR)) { @mkdir($RDIR, 0700, true); }

function kdir($key) {
    if (!preg_match('/^[A-Za-z0-9]{32}$/', $key)) return null;
    $d = $GLOBALS["RDIR"] . "/" . hash("sha256", "zc-relay-" . $key);
    if (!is_dir($d)) { @mkdir($d, 0700, true); }
    return $d;
}
function wjson($f, $data) { @file_put_contents($f, "<?php exit; ?>\n" . json_encode($data)); }
function rjson($f) {
    $c = @file_get_contents($f);
    if ($c === false) return null;
    $c = preg_replace('/^<\?php exit; \?>\n?/', '', $c);
    return json_decode($c, true);
}
function prune($d) {
    $now = time();
    $files = glob($d . "/*.json") ?: [];
    // drop anything older than 2h
    foreach ($files as $f) { if ($now - @filemtime($f) > 7200) @unlink($f); }
    // keep newest 100
    $files = glob($d . "/*.json") ?: [];
    if (count($files) > 100) {
        usort($files, function($a,$b){ return @filemtime($b) - @filemtime($a); });
        foreach (array_slice($files, 100) as $f) @unlink($f);
    }
}

$body = json_decode(@file_get_contents("php://input"), true);
if (!is_array($body)) $body = [];
$action = $body["action"] ?? $_GET["action"] ?? "";
$key = $body["key"] ?? $_GET["key"] ?? "";
$d = kdir($key);
if (!$d) { http_response_code(403); echo json_encode(["error" => "bad_key"]); exit; }
prune($d);

if ($action === "push") {
    // {key, cmd:{action:"navigate"|"read"|"click"|"fill"|"shot", ...}} -> {id}
    $cmd = $body["cmd"] ?? null;
    if (!is_array($cmd) || !isset($cmd["action"])) { echo json_encode(["error" => "bad_cmd"]); exit; }
    $allowed = ["navigate","read","click","fill","shot"];
    if (!in_array($cmd["action"], $allowed, true)) { echo json_encode(["error" => "bad_action"]); exit; }
    // never let the AI touch password fields or chrome:// pages
    if (isset($cmd["url"]) && preg_match('#^(chrome|chrome-extension|about|edge|brave|javascript|data|file|blob):#i', $cmd["url"])) {
        echo json_encode(["error" => "blocked_url"]); exit;
    }
    $id = bin2hex(random_bytes(8));
    wjson($d . "/cmd_" . $id . ".json", ["id" => $id, "cmd" => $cmd, "status" => "pending", "ts" => time()]);
    echo json_encode(["id" => $id]);
    exit;
}

if ($action === "poll") {
    // extension long-polls: returns pending commands and marks them claimed
    $out = [];
    foreach (glob($d . "/cmd_*.json") ?: [] as $f) {
        $j = rjson($f);
        if (is_array($j) && ($j["status"] ?? "") === "pending") {
            $j["status"] = "claimed";
            wjson($f, $j);
            $out[] = ["id" => $j["id"], "cmd" => $j["cmd"]];
        }
    }
    echo json_encode(["commands" => $out]);
    exit;
}

if ($action === "result") {
    // {key, id, ok, data} — extension posts execution result
    $id = preg_replace('/[^a-f0-9]/', '', $body["id"] ?? "");
    if (!$id) { echo json_encode(["error" => "bad_id"]); exit; }
    wjson($d . "/res_" . $id . ".json", ["id" => $id, "ok" => (bool)($body["ok"] ?? false), "data" => $body["data"] ?? null, "ts" => time()]);
    @unlink($d . "/cmd_" . $id . ".json");
    echo json_encode(["saved" => true]);
    exit;
}

if ($action === "get") {
    // {key, id} — Zero AI page polls for the result
    $id = preg_replace('/[^a-f0-9]/', '', $body["id"] ?? ($_GET["id"] ?? ""));
    if (!$id) { echo json_encode(["error" => "bad_id"]); exit; }
    $j = rjson($d . "/res_" . $id . ".json");
    if (!$j) { echo json_encode(["pending" => true]); exit; }
    @unlink($d . "/res_" . $id . ".json"); // delete after read: don't keep page text/screenshots on server
    echo json_encode($j);
    exit;
}

echo json_encode(["error" => "bad_action"]);
